      "id": "BUG-101",
      "tenant": "demo_customer",
      "title": "Duplicate order after checkout retry",
      "body": "A network retry creates a second order. Reproduce by sending the same request twice.",
      "status": "open"
    }
  ]
}

{
  "articles": [
    {
      "id": "KB-001",
      "title": "Checkout idempotency",
      "text": "Use an idempotency key scoped to the customer. In one transaction, lock inventory, validate the quote and persist the order with a unique customer/key constraint. Regression: repeat a request and verify the same order ID and one stock decrement."
    }
  ]
}
